#' Plot *s2dv* postprocessing skill scores
#'
#' @description Plots *s2dv_cube* postprocessing skill scores for gridded,
#' polygon and point data generated by the `c4h_postprocessing` function.
#' It is used for the following statistics: BSS, RPSS, CRPSS, AbsBiasSS,
#' MSSS, RMSSS and ROCSS. For MSE and RMSE, please use the function `c4h_plot`.
#'
#' @param skill *s2dv_cube* object with the skill data to be plotted.
#' @param sign An additional optional binary *s2dv_cube* indicating
#' significance.
#' @param time Numerical index of the time to be plotted. Defaults to NULL (all
#' times).
#' @param boundaries Polygon boundaries to add to the map.  Set to NULL for no
#' boundaries (default), otherwise supply a polygon `sf` object or set to
#' "countries" for coarse country boundaries.
#' @param mask_boundaries If TRUE (default), mask the data to the provided
#' boundaries.
#' @param title Optional plot title.
#' @param legend Optional legend title. If NULL (default), it uses the variable
#' names.
#' @param palette GHR, RColorBrewer or colorspace palette. Use "-" before the
#' palette name (e.g., "-Reds") to reverse it. Alternatively, a vector of
#' hex codes to create a continuous interpolated palette.
#' @param noskillcol Colour for skill scores < 0 depicting a skill lower than
#' climatologies.
#' @param coordgrid If TRUE, display coordinate grids on the map.
#' @param ... Extra arguments indicating fixed aesthetics to be passed to
#'`stars::geom_stars`, including `lwd`, `alpha`, `size` and `colour`.
#' @returns A plot
#' @export
#'
#' @importFrom rlang .data
#'
#' @seealso [c4h_postprocess()] for calculating forcast skill and [c4h_plot()]
#' for general plotting of `s2dv` objects.
#'
#' @examples
#' # DISCLAIMER: The purpose of these examples is to show the functionality
#' # of the different functions. To perform postprocessing, a much larger time
#' # series is required.
#' # Load data
#' hcst <- c4h_load(
#'   system.file("extdata", "hindcast", package = "clim4health"),
#'   variable = "t2m",
#'   year = 2010:2012,
#'   month = 1,
#'   leadtime_month = 1:3,
#'   ext = "nc"
#' )
#' lats <- hcst$coords$latitude
#' lons <- hcst$coords$longitude
#' obs <- c4h_load(
#'   system.file("extdata", "reanalysis", package = "clim4health"),
#'   variable = "t2m",
#'   year = 2010:2012,
#'   month = 1,
#'   leadtime_month = 1:3,
#'   bbox = c(max(lats), min(lons), min(lats), max(lons)),
#'   ext = "nc"
#' )
#'
#' # Example with gridded data
#' dwn <- c4h_downscale(
#'   "Interpolation",
#'   exp = hcst,
#'   obs = obs,
#'   method_remap = "bilinear",
#'   target_grid = system.file(
#'     "extdata",
#'     "reanalysis/t2m_201001.nc",
#'     package = "clim4health"
#'   )
#' )
#' hcst_dwn <- dwn$exp
#' skill_grid <- c4h_postprocess(exp = hcst_dwn, obs = obs, metrics = "BSS")
#' c4h_plotskill(skill_grid$BSS10$rpss, skill_grid$BSS10$sign)
#' # Make some artificial significance for testing
#' skill_grid$BSS10$sign$data[,,,,, 3:8, 15:25] <- TRUE
#' c4h_plotskill(skill = skill_grid$BSS10$rpss, sign = skill_grid$BSS10$sign)
#'
#' # Example with polygon data
#' areas <- sf::read_sf(system.file("extdata", "areas", "munip_vallecauca.gpkg",
#'                                  package = "clim4health"))
#' obs_area <- c4h_space(obs,
#'                       areas = areas,
#'                       fun = "mean",
#'                       areas_id = "munip_code")
#' hcst_area <- c4h_space(hcst,
#'                        areas = areas,
#'                        fun = "mean",
#'                        areas_id = "munip_code")
#' skill_area <- c4h_postprocess(exp = hcst_area,
#'                               obs = obs_area,
#'                               metrics = "CRPSS",
#'                               brier_thresholds = c(0.1, 0.9))
#' c4h_plotskill(skill_area$CRPSS$crpss, skill_area$CRPSS$sign)
#' # Make some artificial significance for testing
#' skill_area$CRPSS$sign$data[1, 1, 1, 1:3, 1, sample(1:42, 10)] <- TRUE
#' c4h_plotskill(skill = skill_area$CRPSS$crpss, sign = skill_area$CRPSS$sign)
#'
#' # Example with station data
#' point_locs <- clim4health::c4h_load(system.file("extdata",
#'                                                "stations",
#'                                                package = "clim4health"),
#'                                     ext = "csv",
#'                                     year = 2010:2012,
#'                                     month = 1,
#'                                     leadtime_month = 1:3,
#'                                     variable = "temp_mean")
#' points <- list(latitude = point_locs$attrs$location$latitude,
#'                longitude = point_locs$attrs$location$longitude)
#' point_locs <- c4h_time(point_locs,
#'                        time_aggregation = "monthly",
#'                        dim_aggregation = "sdate",
#'                        fun = "mean")
#' dwn <- c4h_downscale("Interpolation", exp = hcst,
#'                      points = points, method_point_interp = "bilinear")
#' hcst_dwn <- dwn$exp
#' skill_point <- c4h_postprocess(exp = hcst_dwn,
#'                                obs = point_locs,
#'                                metrics = "BSS")
#' c4h_plotskill(skill = skill_point$BSS10$rpss, boundaries = areas)
#' # Make some artificial significance for testing
#' skill_point$BSS10$sign$data[1, 1, 1, 1:3, 1, 4:6] <- TRUE
#' c4h_plotskill(skill = skill_point$BSS10$rpss,
#'               sign = skill_point$BSS10$sign,
#'               boundaries = areas)

c4h_plotskill <- function(
  skill,
  sign = NULL,
  time = NULL,
  boundaries = NULL,
  mask_boundaries = FALSE,
  title = NULL,
  legend = NULL,
  palette = "SunsetDark",
  noskillcol = "#b7d6ff",
  coordgrid = FALSE,
  ...
) {
  # 1. Data checks ----

  # Get skill array info
  if (inherits(skill, "s2dv_cube")) {
    dims_skill <- skill$dims
    plot_skill <- skill$data
  } else {
    stop("'skill' must be an s2dv array.")
  }

  # Requirements: sdate and ensemble
  if (dims_skill["sdate"] != 1 || dims_skill["ensemble"] != 1) {
    stop(
      "'sdate' and 'ensemble' dimensions must have a length of one. ",
      "Please verify you are plotting the output of c4h_postprocess()"
    )
  }

  # Requirements: skill data
  if (any(plot_skill > 1, na.rm = TRUE)) {
    stop(
      "'skill' data must be lower than 1. Please use 'c4h_plot'",
      " for other metrics such as RMSE and MSE."
    )
  }

  # Get significance array info and requirements
  if (!is.null(sign)) {
    if (inherits(sign, "s2dv_cube")) {
      dims_sign <- sign$dims
      plot_sign <- sign$data
    } else {
      stop("'sign' must be an s2dv array.")
    }
    if (!is.logical(plot_sign)) {
      stop("'sign' data must be of type logical (TRUE/FALSE).")
    }
    if (!identical(dims_skill, dims_sign)) {
      stop("The dimensions of 'skill' and 'sign' must be identical.")
    }
  }

  # Requirements: time
  if (!is.null(time) && !is.numeric(time)) {
    stop("'time' must be of type numeric.")
  } else if (!is.null(time) && any(time > dims_skill["time"])) {
    stop(paste0(
      "A wrong 'time' has been selected (possible range: 1 - ",
      dims_skill["time"],
      ")."
    ))
  } else if (is.null(time)) {
    time <- 1:dims_skill["time"]
  }

  # Requirements: boundaries
  if (!is.null(boundaries)) {
    if (!inherits(boundaries, "sf")) {
      if (boundaries != "countries") {
        stop(
          "'boundaries' must be set to either 'countries' or be a ",
          "polygon 'sf' object."
        )
      }
    }
  }

  # Number of panels
  if (length(time) > 30) {
    warning(paste0(
      "The number of panels is very large, consider selecting a ",
      "smaller set of times."
    ))
  }

  # 2. Data preprocessing ----

  # Select 'time' if needed
  if (all(time %in% 1:dims_skill["time"])) {
    plot_skill <- .subset_array_named(plot_skill, time = time)
    if (!is.null(sign)) {
      plot_sign <- .subset_array_named(plot_sign, time = time)
    }
  }

  # Select boundaries if needed
  if (!is.null(boundaries)) {
    if (inherits(boundaries, "sf")) {
      if (sf::st_crs(boundaries)$epsg != 4326) {
        message("Transforming 'boundaries' to CRS EPSG 4326")
        bound_sf <- sf::st_transform(boundaries, crs = 4326)
      } else {
        bound_sf <- boundaries
      }
    } else if (boundaries == "countries") {
      bound_sf <- spData::world
    }
  }

  # Get varname
  varname <- skill$attrs$Variable$varName

  # 3. Conversion to stars ----
  if ("longitude" %in% names(dims_skill)) {
    # Gridded data ----
    spatial_dims <- c(
      which(names(dim(plot_skill)) == "longitude"),
      which(names(dim(plot_skill)) == "latitude")
    )
    plot_skill <- aperm(
      plot_skill,
      c(spatial_dims, setdiff(seq_along(dims_skill), spatial_dims))
    )
    plot_skill <- stars::st_as_stars(plot_skill)
    names(plot_skill) <- varname
    plot_skill <- stars::st_set_dimensions(
      plot_skill,
      "longitude",
      values = c(skill$coords$longitude)
    )
    plot_skill <- stars::st_set_dimensions(
      plot_skill,
      "latitude",
      values = c(skill$coords$latitude)
    )
    plot_skill <- stars::st_set_dimensions(
      plot_skill,
      "sdate",
      values = c(skill$coords$sdate)
    )
    plot_skill <- stars::st_set_dimensions(
      plot_skill,
      "ensemble",
      values = c(skill$coords$ensemble)
    )
    plot_skill <- stars::st_set_dimensions(
      plot_skill,
      "time",
      values = c(skill$attrs$Date)[time]
    )
    sf::st_crs(plot_skill) <- 4326

    if (!is.null(sign)) {
      plot_sign <- ifelse(is.na(plot_sign), FALSE, plot_sign)
      plot_sign <- aperm(
        plot_sign,
        c(spatial_dims, setdiff(seq_along(dims_skill), spatial_dims))
      )
      plot_skill[["sign"]] <- plot_sign
    }

    # Mask if needed
    if (isTRUE(mask_boundaries) && !is.null(boundaries)) {
      sf::sf_use_s2(FALSE)
      suppressMessages(plot_skill <- plot_skill[bound_sf])
      sf::sf_use_s2(FALSE)
    }
  } else if ("location" %in% names(dims_skill)) {
    # Point data ----

    plot_skill <- aperm(
      plot_skill,
      match(
        c("dataset", "var", "sdate", "time", "ensemble", "location"),
        names(dims_skill)
      )
    )
    lon <- skill$attrs$location$longitude
    lat <- skill$attrs$location$latitude
    point_geom <- sf::st_sfc(
      lapply(seq_along(lon), function(i) sf::st_point(c(lon[i], lat[i]))),
      crs = 4326
    )
    plot_skill <- stars::st_as_stars(
      plot_skill,
      dimensions = stars::st_dimensions(
        dataset = c(skill$coords$dataset),
        var = c(skill$coords$var),
        sdate = c(skill$coords$sdate),
        time = c(skill$attrs$Date)[time],
        ensemble = c(skill$coords$ensemble),
        location = point_geom
      )
    )
    names(plot_skill) <- varname
    if (!is.null(sign)) {
      plot_sign <- ifelse(is.na(plot_sign), FALSE, plot_sign)
      plot_sign <- aperm(
        plot_sign,
        match(
          c("dataset", "var", "sdate", "time", "ensemble", "location"),
          names(dims_sign)
        )
      )
      plot_skill[["sign"]] <- plot_sign
    }
    plot_skill <- sf::st_as_sf(plot_skill, long = TRUE)
  } else if ("area" %in% names(dims_skill)) {
    # Polygon data ----

    plot_skill <- aperm(
      plot_skill,
      match(
        c("dataset", "var", "sdate", "time", "ensemble", "area"),
        names(dims_skill)
      )
    )
    plot_skill <- stars::st_as_stars(
      plot_skill,
      dimensions = stars::st_dimensions(
        dataset = c(skill$coords$dataset),
        var = c(skill$coords$var),
        sdate = c(skill$coords$sdate),
        time = c(skill$attrs$Date)[time],
        ensemble = c(skill$coords$ensemble),
        area = skill$attrs$area$geom
      )
    )
    names(plot_skill) <- varname
    if (!is.null(sign)) {
      plot_sign <- ifelse(is.na(plot_sign), FALSE, plot_sign)
      plot_sign <- aperm(
        plot_sign,
        match(
          c("dataset", "var", "sdate", "time", "ensemble", "area"),
          names(dims_sign)
        )
      )
      plot_skill[["sign"]] <- plot_sign
    }
    plot_skill <- sf::st_as_sf(plot_skill, long = TRUE)
  }

  # 4. Plot ----

  # Binning, reverse factor
  plot_skill[[varname]] <- cut(
    plot_skill[[varname]],
    breaks = c(-Inf, seq(0, 1, by = 0.2)),
    labels = paste0("<", seq(0, 1, by = 0.2))
  )
  plot_skill[[varname]] <- factor(
    plot_skill[[varname]],
    levels = rev(levels(plot_skill[[varname]]))
  )

  # Significance check
  if (!is.null(sign) && sum(plot_skill$sign, na.rm = TRUE) == 0) {
    message("No areas have a significant skill score.")
    sign <- NULL
  }

  # Base plot
  if ("longitude" %in% names(dims_skill)) {
    # Gridded data ----
    p <- ggplot2::ggplot() +
      stars::geom_stars(data = plot_skill, show.legend = TRUE, ...) +
      ggplot2::coord_equal(expand = FALSE) +
      ggplot2::guides(
        fill = ggplot2::guide_legend(
          order = 1,
          override.aes = list(lwd = 0.1, col = "grey10")
        )
      )

    if (!is.null(sign)) {
      # Skill hatching
      skill_simple <- plot_skill[2, drop = TRUE]

      # Loop through time
      skill_polys <- sf::st_sf(geom = sf::st_sfc())
      sf::st_crs(skill_polys) <- 4326 # Empty object to append to
      dim_f1 <- stars::st_get_dimension_values(skill_simple, "time")
      for (i in seq_along(dim_f1)) {
        skill_simple_i <- .slice_stars_dimname(skill_simple, "time", i)
        skill_simple_i <- skill_simple_i[, drop = TRUE]

        skill_polys_i <- sf::st_as_sf(
          skill_simple_i,
          long = TRUE,
          merge = TRUE
        )
        skill_polys_i["time"] <- dim_f1[i]
        skill_polys_i <- skill_polys_i[skill_polys_i$sign == 1, ]
        skill_polys <- rbind(skill_polys, skill_polys_i)
      }

      suppressMessages({
        p <- p +
          ggpattern::geom_sf_pattern(
            data = skill_polys,
            ggplot2::aes(pattern = "Significant"),
            pattern_fill = "black",
            pattern_density = 0.05,
            pattern_alpha = 0.9,
            pattern_spacing = 0.03,
            lwd = 0,
            fill = NA
          ) +
          ggpattern::scale_pattern_manual(
            name = "",
            values = c("Significant" = "stripe")
          ) +
          ggplot2::guides(
            pattern = ggplot2::guide_legend(
              order = 2,
              override.aes = list(
                fill = "white",
                pattern_density = 0.15,
                pattern_spacing = 0.02,
                lwd = 0.2
              )
            )
          ) +
          ggplot2::scale_x_continuous(labels = function(x) {
            paste0(ifelse(x < 0, "-", ""), abs(x))
          }) +
          ggplot2::scale_y_continuous(labels = function(y) {
            paste0(ifelse(y < 0, "-", ""), abs(y))
          })
      })
    }
  } else if ("location" %in% names(dims_skill)) {
    # Point data ----
    if (!is.null(boundaries)) {
      p <- ggplot2::ggplot() +
        ggplot2::geom_sf(
          data = bound_sf,
          alpha = 0,
          col = "grey10",
          linewidth = 0.1,
          inherit.aes = FALSE
        )
    } else {
      p <- ggplot2::ggplot()
    }

    # Skill hatching
    if (!is.null(sign)) {
      p <- p +
        ggplot2::geom_sf(
          data = plot_skill,
          ggplot2::aes(
            colour = .data[[varname]],
            alpha = sign
          ),
          show.legend = TRUE,
          ...
        ) +
        ggplot2::geom_sf(
          data = plot_skill,
          ggplot2::aes(
            colour = .data[[varname]],
          ),
          shape = 21,
          fill = NA,
          ...
        ) +
        ggplot2::scale_alpha_manual(
          values = c("TRUE" = 1, "FALSE" = 0),
          labels = c("No", "Yes")
        ) +
        ggplot2::labs(alpha = "Significant") +
        ggplot2::guides(
          colour = ggplot2::guide_legend(order = 1),
          alpha = ggplot2::guide_legend(
            override.aes = list(
              col = "black",
              fill = c("white", "black"),
              shape = 21,
              alpha = 1
            )
          )
        )
    } else {
      p <- p +
        ggplot2::geom_sf(
          data = plot_skill,
          ggplot2::aes(colour = .data[[varname]]),
          show.legend = TRUE,
          ...
        )
    }
    p <- p +
      ggplot2::coord_sf(
        xlim = sf::st_bbox(plot_skill)[c("xmin", "xmax")],
        ylim = sf::st_bbox(plot_skill)[c("ymin", "ymax")],
        expand = TRUE
      ) +
      ggplot2::scale_x_continuous(labels = function(x) {
        paste0(ifelse(x < 0, "-", ""), abs(x))
      }) +
      ggplot2::scale_y_continuous(labels = function(y) {
        paste0(ifelse(y < 0, "-", ""), abs(y))
      })
  } else if ("area" %in% names(dims_skill)) {
    # Polygon data ----
    if (!is.null(boundaries)) {
      p <- ggplot2::ggplot() +
        ggplot2::geom_sf(
          data = bound_sf,
          alpha = 0,
          col = "grey10",
          linewidth = 0.1,
          inherit.aes = FALSE,
          show.legend = TRUE
        ) +
        ggplot2::geom_sf(
          data = plot_skill,
          ggplot2::aes(fill = .data[[varname]]),
          ...,
          inherit.aes = FALSE
        ) +
        ggplot2::coord_sf(
          xlim = sf::st_bbox(plot_skill)[c("xmin", "xmax")],
          ylim = sf::st_bbox(plot_skill)[c("ymin", "ymax")],
          expand = TRUE
        )
    } else {
      p <- ggplot2::ggplot() +
        ggplot2::geom_sf(
          data = plot_skill,
          ggplot2::aes(fill = .data[[varname]]),
          show.legend = TRUE,
          ...
        )
    }
    p <- p +
      ggplot2::scale_x_continuous(labels = function(x) {
        paste0(ifelse(x < 0, "-", ""), abs(x))
      }) +
      ggplot2::scale_y_continuous(labels = function(y) {
        paste0(ifelse(y < 0, "-", ""), abs(y))
      })
    # Skill hatching
    if (!is.null(sign)) {
      p <- p +
        ggpattern::geom_sf_pattern(
          data = plot_skill[plot_skill$sign, ],
          ggplot2::aes(pattern = "Significant"),
          pattern_fill = "black",
          pattern_density = 0.05,
          pattern_alpha = 0.9,
          pattern_spacing = 0.03,
          lwd = 0,
          fill = NA
        ) +
        ggpattern::scale_pattern_manual(
          name = "",
          values = c("Significant" = "stripe")
        ) +
        ggplot2::guides(
          fill = ggplot2::guide_legend(order = 1),
          pattern = ggplot2::guide_legend(
            override.aes = list(
              fill = "white",
              pattern_density = 0.2,
              pattern_spacing = 0.01,
              lwd = 0.2
            )
          )
        )
    }
  }

  # Wrap
  p <- p +
    ggplot2::facet_wrap(stats::as.formula("~time"), labeller = "label_both")

  # Palette ----
  level_names <- levels(plot_skill[[varname]])
  level_names <- level_names[!is.na(level_names)]
  my_palette <- GHRexplore::GHR_palette(palette)(
    n = length(level_names) - 1
  )
  my_palette <- c(my_palette, noskillcol) # Colour for non-significant
  names(my_palette) <- level_names
  if ("location" %in% names(dims_skill)) {
    p <- p +
      ggplot2::scale_colour_manual(
        values = my_palette,
        na.value = "grey70",
        drop = FALSE
      )
  } else if ("area" %in% names(dims_skill)) {
    p <- p +
      ggplot2::scale_fill_manual(
        values = my_palette,
        na.value = "grey70",
        drop = FALSE
      )
  } else {
    p <- p +
      ggplot2::scale_fill_manual(
        values = my_palette,
        na.value = "#FFFFFF00",
        drop = FALSE
      )
  }

  # Boundaries on top, only for grid
  if (!is.null(boundaries) && "longitude" %in% names(dims_skill)) {
    suppressMessages(
      p <- p +
        ggplot2::geom_sf(
          data = bound_sf,
          alpha = 0,
          col = "grey10",
          linewidth = 0.1,
          inherit.aes = FALSE
        ) +
        ggplot2::coord_sf(
          xlim = sf::st_bbox(plot_skill)[c("xmin", "xmax")],
          ylim = sf::st_bbox(plot_skill)[c("ymin", "ymax")],
          expand = TRUE
        ) +
        ggplot2::scale_x_continuous(labels = function(x) {
          paste0(ifelse(x < 0, "-", ""), abs(x))
        }) +
        ggplot2::scale_y_continuous(labels = function(y) {
          paste0(ifelse(y < 0, "-", ""), abs(y))
        })
    )
  }

  # Theme
  if (isTRUE(coordgrid)) {
    p <- p +
      ggplot2::theme_minimal() +
      ggplot2::theme(
        plot.margin = ggplot2::theme_bw()$plot.margin,
        panel.background = ggplot2::element_rect(
          fill = NA,
          color = "grey10",
          linewidth = 0.1
        ),
        panel.grid.minor = ggplot2::element_blank(),
        panel.grid.major = ggplot2::element_line(linewidth = 0.3),
        axis.ticks = ggplot2::element_line(linewidth = 0.3, color = "grey40"),
        axis.text = ggplot2::element_text(size = 7, color = "grey30"),
        strip.text.y = ggplot2::element_text(margin = ggplot2::margin(b = 0)),
        strip.text.x = ggplot2::element_text(margin = ggplot2::margin(b = 0))
      ) +
      ggplot2::xlab("") +
      ggplot2::ylab("")

    if (!isTRUE(coordgrid)) {
      p <- p +
        ggplot2::theme(strip.text.y = ggplot2::element_text(angle = 90))
    }
  } else {
    p <- p +
      ggplot2::theme_void() +
      ggplot2::theme(
        plot.margin = ggplot2::theme_bw()$plot.margin,
        strip.text.y = ggplot2::element_text(
          angle = 90,
          margin = ggplot2::margin(b = 0)
        ),
        strip.text.x = ggplot2::element_text(margin = ggplot2::margin(b = 0)),
        panel.border = ggplot2::element_rect(
          color = "black",
          fill = NA,
          linewidth = 0.1
        )
      )
  }

  # Labels
  if (!is.null(title)) {
    p <- p + ggplot2::ggtitle(title)
  }
  if (!is.null(legend)) {
    if (!"location" %in% names(dims_skill)) {
      p <- p + ggplot2::labs(fill = legend)
    } else {
      p <- p + ggplot2::labs(col = legend)
    }
  }

  return(p)
}
